      COMMIT;
    `);
  }

  const reviewCols = cols("celeb_review_queue");
  if (reviewCols.size && !reviewCols.has("proposed_candidates")) {
    db.exec(`ALTER TABLE celeb_review_queue ADD COLUMN proposed_candidates TEXT`);
