const deathBrief = require("./death-brief");

const SUFFIX_RE = /\s*\[[a-zA-Z]{2,3}\]\s*$/;

/** nameKey-Analogon ohne Netz — nur für den Namensvergleich Nicht-Mensch vs Mensch.
 *  Nimmt den ersten Komma-Teil („Young L, 39, Rapper“ → „Young L“) + Suffix-Strip. */
function normName(s) {
  const first = String(s || "").split(",")[0] || "";
  return first
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(SUFFIX_RE, "")
    .replace(/[^\p{L}\p{N}]/gu, "");
}

/**
 * Reine, netzfreie Dedup-Entscheidung VOR dem Posten der All-Deaths-Karten.
 *
 * Eingabe: aufgelöste Entries (Auflösung in wiki-poll.js → fetchDeathBrief).
 * @param {Array<object>} entries Aufzulösende Entries:
 *   { id, lang, url, text, redName, listUrl, resolved: { qid, isHuman, url, pageMissing, error } }
 * @param {{ qids: Set<string>, humanNames: Set<string> }} history
 *   QIDs + Namen der zuletzt geposteten Karten.
 * @returns {{ post: object[], bind: Array<{loserId:string, winnerId:string}>, defer: object[] }}
 */
function planAnnouncements(entries, history) {
  const post = [];
  const bind = [];
  const defer = [];
  const qids = new Set(history?.qids || []);
  const historyNames = new Set([...(history?.humanNames || [])].map((n) => normName(n)));
  const postedHumanNames = new Map(); // normName -> winner entry

  // Auflösungs-Fehler sind KEIN "kein EN": sie werden vertagt (nicht gepostet,
  // nicht gestempelt) und beim nächsten Poll erneut versucht.
  const resolveErrors = entries.filter((e) => e?.resolved?.error);
  defer.push(...resolveErrors);

  // ----- Pass 1: Menschen -----
  // 1a) Mit QID: pro QID eine Karte (EN vor de, nicht-redName vor redName).
  const byQid = new Map();
  for (const e of entries) {
    if (e.resolved?.error) continue;
    if (e.resolved?.qid && e.resolved?.isHuman === true) {
      if (!byQid.has(e.resolved.qid)) byQid.set(e.resolved.qid, []);
      byQid.get(e.resolved.qid).push(e);
    }
  }
  for (const [qid, group] of byQid) {
    if (qids.has(qid)) {
      // historisch schon gepostet — nichts posten; alle stempeln
      for (const e of group) bind.push({ loserId: e.id, winnerId: e.id });
      continue;
    }
    const rank = (e) => {
      let r = 0;
      if (e.lang === "en") r += 100;
      if (!e.redName) r += 10;
      if (e.lang === "en" && e.url && /en\.wikipedia/i.test(e.url)) r += 1;
      return r;
    };
    group.sort((a, b) => rank(b) - rank(a));
    const winner = group[0];
    post.push(winner);
    postedHumanNames.set(normName(deathBrief.personNameFromText(winner.text)), winner);
    for (const e of group.slice(1)) bind.push({ loserId: e.id, winnerId: winner.id });
    qids.add(qid);
  }

  // 1b) Menschen ohne QID: werden gepostet (kein QID-Dedup), Name für Nicht-Mensch-Match merken.
  const soloHumans = [];
  for (const e of entries) {
    if (e.resolved?.error) continue;
    if (e.resolved?.qid && e.resolved?.isHuman === true) continue; // in 1a
    if (e.resolved?.isHuman !== true) continue;
    const nk = normName(deathBrief.personNameFromText(e.text));
    if (nk) postedHumanNames.set(nk, e);
    soloHumans.push(e);
  }
  post.push(...soloHumans);

  // ----- Pass 2: Nicht-Menschen / redName ohne Personenseite -----
  for (const e of entries) {
    if (e.resolved?.error) continue; // schon in defer
    if (e.resolved?.qid && e.resolved?.isHuman === true) continue; // in Pass 1
    if (e.resolved?.isHuman === true) continue; // solo human in 1b
    const nk = normName(deathBrief.personNameFromText(e.text));
    // Regel 4: Nicht-Mensch/redName nur posten, wenn der Name keinem Menschen
    // aus diesem Batch und keinem recentHistory entspricht.
    if (nk && (postedHumanNames.has(nk) || historyNames.has(nk))) {
      const winner = postedHumanNames.get(nk);
      bind.push(winner ? { loserId: e.id, winnerId: winner.id } : { loserId: e.id, winnerId: e.id });
      continue;
    }
    post.push(e);
  }

  return { post, bind, defer };
}

module.exports = { planAnnouncements, normName };

/**
 * Log-Kanal-Helfer.
 *
 * Schreibt Eingaben, Änderungen und Fehler (inkl. technischer Details) in einen
 * konfigurierbaren Discord-Kanal (CHANNEL_LOG). Ausdrücklich KEINE Logs über die
 * Wiki-Scan-Runs (Poll-Läufe, Scrape-Zähler) — die bleiben auf stdout.
 *
 * Verhalten:
 * - CHANNEL_LOG leer oder Kanal nicht erreichbar: console.warn und zurückkehren —
 *   der Aufrufer läuft immer weiter (Failsafe wie sendAdmin).
 * - In-Memory-Queue mit einem Consumer und Mindestabstand, damit ein Fehlersturm
 *   das Gateway nicht mit Discord-Rate-Limits trifft.
 * - scrub() entfernt Tokens/Secrets aus Nachricht und Stack.
 * - kind === "scan" wird verworfen (Regel: keine Scan-Logs im Logkanal).
 */
const { EmbedBuilder } = require("discord.js");

const QUEUE_INTERVAL_MS = 1000;
let queue = [];
let consumerRunning = false;
const warnedOnce = new Set();

function scrubText(text, config) {
  let s = String(text ?? "");
  const secrets = new Set();
  if (config?.token && String(config.token).length >= 8) secrets.add(String(config.token));
  if (process.env.TOKEN && String(process.env.TOKEN).length >= 8) secrets.add(String(process.env.TOKEN));
  for (const secret of secrets) s = s.split(secret).join("[REDACTED]");
  return s.replace(
    /\b(mfa\.[A-Za-z0-9_-]{80,}|[A-Za-z0-9_-]{20,26}\.[\w-]{5,}\.[\w-]{30,40})\b/g,
    "[REDACTED]"
  );
}

async function drain() {
  consumerRunning = true;
  while (queue.length) {
    const item = queue.shift();
    const target = await item.client.channels.fetch(item.config.channelLog).catch(() => null);
    if (!target?.isTextBased?.(false)) {
      const key = "no-channel";
      if (!warnedOnce.has(key)) {
        warnedOnce.add(key);
        console.warn("[log] CHANNEL_LOG nicht erreichbar — Log-Events entfallen.");
      }
      continue;
    }
    try {
      await target.send({
        content: item.content || null,
        embeds: item.embeds && item.embeds.length ? item.embeds : undefined,
        allowedMentions: { parse: [] },
      });
    } catch (e) {
      console.warn("[log] send failed", e.message);
    }
    if (queue.length) await new Promise((r) => setTimeout(r, QUEUE_INTERVAL_MS));
  }
  consumerRunning = false;
}

function enqueue(client, config, { kind, content, embeds }) {
  if (kind === "scan") return;
  if (!config?.channelLog) return; // leeres CHANNEL_LOG = No-Op, Bot bleibt startbar
  queue.push({ client, config, kind, content, embeds });
  if (!consumerRunning) drain().catch((e) => console.warn("[log] drain failed", e.message));
}

function buildErrorEmbed(err, { where, userId }) {
  const message = scrubText(String(err?.message || err || "Unbekannter Fehler"));
  let stack = scrubText(err?.stack ? String(err.stack) : "");
  const status = err?.response?.status ?? err?.status;
  const code = err?.code ?? err?.rawError?.code;
  const lines = [
    `**Wo:** ${where || "?"}`,
    userId ? `**User:** ${userId}` : null,
    status ? `**HTTP:** ${status}` : null,
    code ? `**Code:** ${code}` : null,
    "",
    `\`\`\`\n${message.slice(0, 1500)}\n\`\`\``,
  ]
    .filter(Boolean)
    .join("\n");
  const embed = new EmbedBuilder()
    .setColor(0xd0342c)
    .setTitle("Fehler")
    .setDescription(lines.slice(0, 1800))
    .setTimestamp(new Date());
  if (stack) embed.addFields({ name: "Stack", value: `\`\`\`\n${stack.slice(0, 1500)}\n\`\`\`` });
  return embed;
}

/**
 * Logge ein Ereignis (Eingabe/Änderung) in den Logkanal.
 * kind === "scan" wird verworfen.
 */
async function logEvent(client, config, { kind, summary, userId, detail }) {
  if (kind === "scan") return;
  if (!config?.channelLog) return;
  const parts = [
    `**${kind}**`,
    userId ? `(User ${userId})` : null,
    scrubText(summary, config),
    detail ? `\`\`\`\n${scrubText(detail, config).slice(0, 1400)}\n\`\`\`` : null,
  ].filter(Boolean);
  enqueue(client, config, { kind, content: parts.join(" ") });
}

/** Logge einen Fehler inkl. Stack + HTTP-Status in den Logkanal. */
async function logError(client, config, err, { where, userId } = {}) {
  if (!err) return;
  if (!config?.channelLog) return;
  const canonErr = err && typeof err === "object" ? err : new Error(String(err));
  enqueue(client, config, {
    kind: "error",
    embeds: [buildErrorEmbed(canonErr, { where, userId })],
  });
}

