const axios = require("axios");
const cheerio = require("cheerio");
const { wikiPathFromHref } = require("./scraper-en");

const MONTHS = [
  "Januar", "Februar", "März", "April", "Mai", "Juni",
  "Juli", "August", "September", "Oktober", "November", "Dezember",
];

function createClient(userAgent) {
  return axios.create({
    timeout: 30000,
    headers: { "User-Agent": userAgent },
  });
}

async function resolveEnglish(client, germanUrl) {
  // Network/HTTP failures must NOT be treated as "no EN variant": they are
  // transient, and posting the DE entry as DE-only would violate the EN-first
  // rule. Only a successfully loaded page WITHOUT an EN interwiki link means
  // "no EN". Let HTTP/network errors propagate so the poller can defer the DE
  // entry (retry next poll) instead of misrouting it to DE-only.
  const response = await client.get(germanUrl);
  const $ = cheerio.load(response.data);
  const href =
    $('li.interlanguage-link.interwiki-en a').attr("href") ||
    $('a[lang="en"][hreflang="en"]').attr("href") ||
    $('a[lang="en"]').attr("href") ||
    $(".interlanguage-link-en a").attr("href") ||
    null;
  return href || null;
}

function extractFromLists($, lang, listUrl) {
  const entries = [];
  const seen = new Set();
  $(".mw-parser-output ul li").each((_, el) => {
    const $el = $(el);
    if ($el.parents("#toc, .navbox, .reflist, .references").length > 0) return;

    let wikiPath = null;
    $el.find("a").each((__, a) => {
      if (wikiPath) return;
      wikiPath = wikiPathFromHref($(a).attr("href"), lang);
    });
    if (!wikiPath) return;
    if (/^\/wiki\/Nekrolog/i.test(wikiPath)) return;

    const text = $el
      .text()
      .replace(/\[\d+\]/g, "")
      .trim()
      .replace(/^\d+\.\s+\w+\.?\s+/, "");
    if (text.length < 5) return;
    if (/^Nekrolog\b/i.test(text)) return;
    // Drop CSS/markup fragments leaked into list items
    if (/(color:inherit|\{[^}]{2,}\}|^\.[a-z-]+\s*\{|^#\w+\s*\{)/i.test(text)) return;

    const id = `${lang}:${wikiPath}`;
    if (seen.has(id)) return;
    seen.add(id);
    entries.push({
      id,
      wikiPath,
      text,
      url: `https://${lang}.wikipedia.org${wikiPath}`,
      lang,
      ...(listUrl ? { listUrl } : {}),
    });
  });
  return entries;
}

/**
 * Red link ("Seite nicht vorhanden"): no article behind it. Parsoid HTML keeps
 * the /wiki/ path (`/wiki/X?action=edit&redlink=1`), so wikiPathFromHref alone
 * would accept it as an article.
 */
function isRedLink($a) {
  return $a.hasClass("new") || /[?&]redlink=1\b/.test(String($a.attr("href") || ""));
}

/** Modern DE nekrolog months use wikitable rows: Tag | Name | Beruf | Alter | Beleg */
function extractFromTables($, lang, listUrl) {
  const entries = [];
  const seen = new Set();
  $(".mw-parser-output table.wikitable tr").each((_, el) => {
    const $el = $(el);
    if ($el.find("th").length) return; // header

    let wikiPath = null;
    let nameText = "";
    let redName = false;
    // The person is always the person: only the Name column (usually 2nd td)
    // supplies the displayed name. A red-linked (no article) or unlinked name is
    // still a real person — keep the row, mark it redName, and use the best
    // other link in the row (band / party / occupation) only as a research
    // target for the image. The card itself is then built from the death-list
    // entry (fetchDeathBrief + announce handle redName).
    const tds = $el.find("td");
    const nameCell = tds.eq(1).length ? tds.eq(1) : $el;
    nameCell.find("a").each((__, a) => {
      const $a = $(a);
      if (isRedLink($a)) {
        redName = true;
        nameText = $a.text().trim();
        return false;
      }
      const path = wikiPathFromHref($a.attr("href"), lang);
      if (path) {
        wikiPath = path;
        nameText = $a.text().trim();
        return false;
      }
    });
    if (!nameText) {
      // unlinked name cell: person is valid, only a research link is missing
      nameText = nameCell.text().trim();
      redName = true;
    }
    if (!wikiPath && redName) {
      // No article for the person: first non-red link of the row becomes the
      // research target (band/party/occupation). The name stays from the row.
      $el.find("a").each((__, a) => {
        if (wikiPath) return false;
        const $a = $(a);
        if (isRedLink($a)) return true;
        const path = wikiPathFromHref($a.attr("href"), lang);
        if (path) {
          wikiPath = path;
          return false;
        }
      });
    }
    if (!nameText.trim()) return;
    if (!wikiPath) return;
    // Skip links to other nekrolog index pages
    if (/^\/wiki\/Nekrolog/i.test(wikiPath)) return;

    // Refs/ranges must not merge into one number: "85[1]" → 85, "85–86" → 85.
    const ageMatch = tds.eq(3).text().replace(/\[\d+\]/g, "").match(/\d{1,3}/);
    const age = ageMatch ? ageMatch[0] : "";
    const beruf = tds.eq(2).text().replace(/\[\d+\]/g, "").replace(/\s+/g, " ").trim();
    const tag = tds.eq(0).text().trim();
    const text = [nameText, age && `${age}`, beruf, tag].filter(Boolean).join(", ");

    // Day-of-death: DE month tables put "8. Oktober" in the first column
    // (with or without a year for entries from a different year).
    const deathDate = parseDeDate(tag);

    // redName entries share no article URL (the research link is per-row), so
    // dedup on the name instead of the research target — two red "deutscher
    // Schauspieler" rows must not collapse into one entry.
    const id = redName ? `${lang}:red:${nameText}` : `${lang}:${wikiPath}`;
    if (seen.has(id)) return;
    seen.add(id);
    entries.push({
      id,
      wikiPath,
      text,
      url: `https://${lang}.wikipedia.org${wikiPath}`,
      lang,
      ...(redName ? { redName: true } : {}),
      ...(beruf ? { beruf } : {}),
      ...(deathDate ? { ...deathDate } : {}),
      ...(listUrl ? { listUrl } : {}),
    });
  });
  return entries;
}

const MONTHS_DE_IDX = [
  "Januar", "Februar", "März", "April", "Mai", "Juni",
  "Juli", "August", "September", "Oktober", "November", "Dezember",
];

/** Parse "8. Oktober" (optionally "8. Oktober 2026") into {day,month[,year]}. */
function parseDeDate(tag) {
  if (!tag) return null;
  const m = String(tag).match(/(\d{1,2})\s*\.\s*([A-Za-zäöüÄÖÜ]+)\s*(\d{4})?/);

  for (const a of anchors) {
    const href = $el.find(a).attr("href") || a.attribs?.href;
    const path = wikiPathFromHref(href, lang);
    if (path) return path;
  }
  // cheerio element form
  for (const a of anchors) {
    const href = cheerio.load(a)("a").attr("href") || (a.attribs && a.attribs.href);
    const path = wikiPathFromHref(href, lang);
    if (path) return path;
  }
  return null;
}

/**
 * Red link (no article): Parsoid/HTML keeps /wiki/X?action=edit&redlink=1.
 */
function isRedLink(a) {
  const href = String(a?.attribs?.href ?? a?.href ?? "") + (a?.attr ? String(a.attr("href") || "") : "");
  return String(a?.attribs?.class || "").split(/\s+/).includes("new") || /[?&]redlink=1\b/.test(href) || /[?&]redlink=/i.test(href);
}

/**
 * True when a wiki path points to a LIST / navigational article (deaths index,
 * day-of-year lists, births lists) instead of a biography. Entries that link to
 * these must never be announced as deaths.
 */
function isListPagePath(path) {
  if (!path) return false;
  return /^\/wiki\/(Deaths_in_|Nekrolog|List_of_days|List_of_deaths|Lists_of_deaths|List_of_births|Lists_of_births|Category:|Template:|Help:|Wikipedia:|Portal:)/i.test(
    path
  );
}

/** True when entry text is clearly a section/navigation line, not a person. */
function isNavText(text) {
  if (!text) return false;
  return /^(Deaths in |Nekrolog|List of |Lists of |The following is a list|Wikimedia list|Previous |External links|References|See also|Navigation)/i.test(
    String(text).trim()
  );
}

function extractEntriesFromHtml(html, lang, listUrl) {
  const $ = cheerio.load(html);
  const entries = [];
  const seen = new Set();

  // listUrl: die gerade geholte Listen-/Monats-URL — für den „Kein eigener
  // Artikel“-Fall (F05/F02) als verlässliche Fallback-Quelle.

  $(".mw-parser-output ul li").each((_, el) => {
    const $el = $(el);
    if ($el.parents("#toc, .navbox, .reflist, .references").length > 0) return;

    // Ersten blauen Link als id/url nehmen; Rotlink als erster Anker ⇒ redName
    let wikiPath = null;
    let redName = false;
    $el.find("a").each((__, a) => {
      const $a = $(a);
      const href = $a.attr("href");
      if (isRedLink($a)) {
        redName = true;
        // rotlinks dürfen NICHT zur ID werden (Query ist schon abgeschnitten),
        // aber wir brauchen einen blauen Treffer, falls vorhanden.
        const p = wikiPathFromHref(href, lang);
        if (p && !wikiPath) wikiPath = p;
        return true; // weiter, ein späterer blauer Link zählt mehr
      }
      const p = wikiPathFromHref(href, lang);
      if (p) {
        wikiPath = p;
        return false; // erster blauer Link gewinnt
      }
      return true;
    });
    // Drop entries pointing to Wikipedia list/nav pages (the EN wiki now keeps
    // finished months on their own pages and lists them in "Previous months"
    // div-col / footer navboxes — those must not be treated as deaths).
    if (!wikiPath || isListPagePath(wikiPath)) return;

    const text = $el.text().replace(/\[\d+\]/g, "").trim();
    if (text.length < 5) return;
    // Skip legend / instruction lines
    if (/^Name, age, country/i.test(text)) return;
    // Skip navigation / list-article text (robust against future nav formats)
    if (isNavText(text)) return;

    // Die id bleibt IMMER en:${wikiPath} (auch bei Rotlink) — eine neue
    // en:red:-Form würde schon gesehene Rotlink-Personen unter neuer ID
    // erneut announcen. Die Dedup-Entscheidung fällt in planAnnouncements.
    const id = `${lang}:${wikiPath}`;
    if (seen.has(id)) return;
    seen.add(id);

    // Day of death: the month page groups entries under a numeric day heading
    // (H3). Read the closest preceding day heading so the all-deaths card can
    // show the date instead of an empty/uneven entry.
    const $ul = $el.closest("ul");
    let day = null;
    const $prev = $ul.prev();
    if ($prev.is("h3")) {
      day = parseDayId($prev.attr("id"));
    } else {
      const $h3 = $prev.find("h3").first();
      day = parseDayId($h3.attr("id"));
    }
    if (day == null) {
      // fallback: any preceding heading in this month section
      const $h = $ul.prevAll("div.mw-heading3 h3, h3").first();
      day = parseDayId($h.attr("id"));
    }

    entries.push({
      id,
      wikiPath,
      text,
      url: `https://${lang}.wikipedia.org${wikiPath}`,
      lang,
      ...(redName ? { redName: true } : {}),
      ...(listUrl ? { listUrl } : {}),
      ...(day != null ? { day } : {}),
    });
  });

  // listUrl übergeben wir über einen Closure-Global, gesetzt von scrapeUrl.
  listUrlRef = null;
  return entries;
}


function parseDayId(id) {
  if (!id) return null;
  const m = String(id).match(/^(\d{1,2})$/);
  return m ? parseInt(m[1], 10) : null;
}

async function scrapeUrl(client, url, lang = "en") {
  try {
    const response = await client.get(url);
    return extractEntriesFromHtml(response.data, lang, url);
  } catch (e) {
    console.error("[wiki-en]", url, e.message);
    return [];
  }
}

function monthUrl(year, monthIndex) {
  return `https://en.wikipedia.org/wiki/Deaths_in_${MONTHS[monthIndex]}_${year}`;
}

/** Month index + year a deaths URL refers to (0-11), or null. */
function monthFlagsFromUrl(url, year, monthIndex) {
  const m = String(url).match(/Deaths_in_([A-Za-z]+)_(\d{4})/);
  if (m) {
    const idx = MONTHS.indexOf(m[1]);
    if (idx !== -1) return { month: idx, year: parseInt(m[2], 10) };
    return null;
  }
  // "Deaths_in_<Year>" == the current, incomplete month
  return { month: monthIndex, year };
}

/**
 * @param {string} userAgent
 * @param {{ scope?: 'recent'|'full' }} [opts]
 * recent = current + previous month; full = current month + all months YTD
 *
 * Since Oct 2026 the EN wiki splits FINISHED months onto their own
 * "Deaths_in_<Month>_<Year>" pages (like the German wiki), while the current
 * (unfinished) month stays on "Deaths_in_<Year>" together with a
 * "Previous months" div-col navigation section. The current month is always
 * read from the year page; older months come from their standalone pages.
 * "Deaths_in_October_2026" itself redirects to the year page, so it must not
 * be fetched separately (the year page already provides it).
 */
async function scrapeEn(userAgent, opts = {}) {
  const scope = opts.scope || "full";
  const client = createClient(userAgent);
  const year = new Date().getFullYear();
  const monthIndex = new Date().getMonth();
  const urls = [];

  // Current (incomplete) month lives on the year page.
  urls.push(`https://en.wikipedia.org/wiki/Deaths_in_${year}`);

  const prevYear = monthIndex === 0 ? year - 1 : year;
  const prevMonth = monthIndex === 0 ? 11 : monthIndex - 1;

  if (scope === "recent") {
    urls.push(monthUrl(prevYear, prevMonth));
  } else {
    // finished months: Jan..previous month standalone pages
    for (let i = 0; i < monthIndex; i++) urls.push(monthUrl(year, i));
  }

  const results = [];
  for (const u of urls) {
    const flag = monthFlagsFromUrl(u, year, monthIndex);
    const scraped = await scrapeUrl(client, u, "en");
    if (flag) {
      for (const e of scraped) {
        e.month = flag.month;
        e.year = flag.year;
      }
    }
    results.push(scraped);
  }
  const seen = new Set();
  const unique = [];
  for (const e of results.flat()) {
    if (!seen.has(e.id)) {
      seen.add(e.id);
      unique.push(e);
    }
  }
  console.log(`[wiki-en] scraped ${unique.length} entries from ${urls.length} urls (scope=${scope})`);
  return unique;
}

