  }
  const seen = new Set();
  const unique = [];
  for (const e of results.flat()) {
    if (!seen.has(e.id)) {
      seen.add(e.id);
      unique.push(e);
    }
  }
  console.log(`[wiki-de] scraped ${unique.length} entries from ${urls.length} urls (scope=${scope})`);
  return {
    entries: unique,
    resolveEnglish: (germanUrl) => resolveEnglish(client, germanUrl),
  };
}

