const db = require("../db");

/**
 * Darf der User an der announced-Saison teilnehmen?
 *
 * Prüft gegen die ANNOUNCED-Saison (2027): Kanal vorhanden, `live = 0`,
 * User hat `ViewChannel` auf genau diesem Kanal. Die running-Saison (2026)
 * geht NICHT in diese Funktion ein — 2026 live lässt den Assistenten offen,
 * sobald 2027 announced ist und einen Kanal hat.
 *
 * Admin (config.adminId) darf auch ohne ViewChannel (Flow vor erstem echten
 * Teilnehmer prüfbar) — announced-Saison muss trotzdem live=0 und Kanal haben.
 *
 * @returns {{ ok: boolean, reason?: "closed"|"channel"|"not-member", season?: object }}
 */
async function canParticipate(client, config, userId) {
  const season = db.getAnnouncedSeason();
  if (!season || !season.announce_channel_id || season.phase !== "announced" || season.live !== 0) {
    return { ok: false, reason: "closed" };
  }

  const channel = await client.channels.fetch(season.announce_channel_id).catch(() => null);
  if (!channel?.guild) {
    return { ok: false, reason: "channel" };
  }

  try {
    const member = await channel.guild.members.fetch(userId);
    if (member) {
      const perms = channel.permissionsFor(member);
      if (!perms?.has("ViewChannel")) {
        return { ok: false, reason: "not-member" };
      }
      return { ok: true, season };
    }
  } catch (e) {
    // 10007 = Unknown Member
    if (e?.code === 10007 || e?.message?.includes("Unknown Member")) {
      // Admin darf auch ohne Membership durch (Test-/Prüfflow vor echtem Teilnehmer)
      if (String(userId) === String(config.adminId)) return { ok: true, season };
      return { ok: false, reason: "not-member" };
    }
  }

  // Admin-Fallback für sonstige Fetch-Edge-Fälle
  if (String(userId) === String(config.adminId)) return { ok: true, season };
  return { ok: false, reason: "not-member" };
}

module.exports = { canParticipate };

/**
 * Tipp-Liste parsen (Selbstbedienung per PM).
 *
 * Trenner:
 * - Zeilenumbruch trennt immer.
 * - Innerhalb einer Zeile: `;`, ` – `, ` — `, ` - ` (Bindestrich NUR mit Leerzeichen beiderseits).
 * - Komma und Binnen-Bindestrich trennen NICHT (Müller, Hans bleibt ein Name; Jean-Luc bleibt ein Name).
 *
 * Eigenschaften:
 * - Leere Tokens werden verworfen.
 * - Doppelte Namen in derselben Paste (nach nameKey) werden zusammengelegt und gemeldet.
 */

/** Normalisierter Schlüssel für Duplikat-Erkennung in derselben Paste. */
function nameKey(name) {
  return String(name)
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

function splitBySeparators(text) {
  const t = String(text || "");
  // Zeilen, dann in Zeilen an ; und Dash-mit-Space trennen
  const tokens = [];
  for (const line of t.split(/\n+/)) {
    const parts = line
      .split(/;\s*|(?<=[–—])\s|\s+[-–—]\s+/u)
      .map((s) => s.replace(/^[;\s\-–—]+|[;\s\-–—]+$/g, "").trim())
      .filter(Boolean);
    tokens.push(...parts);
  }
  return tokens;
}

/**
 * @returns {{ names: string[], error?: string, duplicates: string[] }}
 */
function parsePickList(text) {
  if (!text || !String(text).trim()) {
    return { names: [], error: "Keine Namen erkannt." };
  }
  const tokens = splitBySeparators(text);
  const names = [];
  const duplicates = [];
  const seen = new Set();
  for (const t of tokens) {
    const k = nameKey(t);
    if (!k) continue;
    if (seen.has(k)) {
      duplicates.push(t);
      continue;
    }
    seen.add(k);
    names.push(t);
  }
  return { names, duplicates };
}

module.exports = { parsePickList, nameKey };

